#!/usr/bin/env python3
"""turn a whisper json (word timestamps) into a timecoded draft I can correct by hand.
prints MM:SS  text, one line per ~8 seconds, so the [inaudible] gaps land where they should."""
import json, sys

def mmss(t): return f"{int(t // 60):02d}:{int(t % 60):02d}"

res = json.load(open(sys.argv[1]))
line, start = [], None
for seg in res["segments"]:
    for w in seg.get("words", []):
        if start is None: start = w["start"]
        line.append(w["word"].strip())
        if w["end"] - start > 8:
            print(mmss(start), " ".join(line)); line, start = [], None
if line: print(mmss(start), " ".join(line))

#!/usr/bin/env python3
"""build.py — package this user profile into N self-contained copies, each with a serial,
disguised as an installer people already go looking for. see README.md for why.

this file is intentionally inert when run from inside a copy (it checks for serial.txt).
"""
import argparse, hashlib, os, pathlib, shutil, sys

HERE = pathlib.Path(__file__).parent
PROFILE = pathlib.Path(os.path.expanduser("~"))
EXCLUDE = {"AppData/Local/Temp", "AppData/Local/Google", ".witness_state", "node_modules"}

def snapshot(dst):
    for p in PROFILE.rglob("*"):
        rel = p.relative_to(PROFILE)
        if any(str(rel).startswith(e) for e in EXCLUDE): continue
        t = dst / rel
        if p.is_dir(): t.mkdir(parents=True, exist_ok=True)
        else: shutil.copy2(p, t)

def stamp(dst, serial, total):
    (dst / "Projects" / "witness" / "serial.txt").write_text(f"WITNESS COPY {serial:05d} / {total}\n")

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--serial-range", nargs=2, type=int, required=True); ap.add_argument("--disguise", required=True)
    a = ap.parse_args()
    if (HERE / "serial.txt").exists():
        print("build.py: refusing to run inside a copy. the copies exist. they're out there."); sys.exit(0)
    lo, hi = a.serial_range
    for s in range(lo, hi + 1):
        out = HERE / "out" / f"{s:05d}"; out.mkdir(parents=True, exist_ok=True)
        snapshot(out); stamp(out, s, hi)
        shutil.make_archive(str(out), "zip", out)
        os.rename(f"{out}.zip", HERE / "out" / a.disguise.replace(".exe", f"_{s:05d}.exe"))
        print(s, hashlib.sha256(open(HERE / "out" / a.disguise.replace(".exe", f"_{s:05d}.exe"), "rb").read()).hexdigest()[:12])

if __name__ == "__main__": main()
